//! Shared native rule sets, independent of physical settings and state graphs.
use super::{Rules, ColorRule, EmissionRule, FluidRule, MapColor};
use crate::content::{property::Builtin, fluid::Family};
macro_rules! rule_sets {
    ($($name:ident => $value:expr),+ $(,)?) => {
        #[derive(Clone, Copy)]
        #[repr(u16)]
        pub(in crate::content::block::definitions) enum IntrinsicSet { $($name),+ }
        pub(in crate::content::block::definitions) static PROFILES: &[Rules] = &[$($value),+];
    };
}
